import{_ as o}from"./chunks/hamburger_menu.BLyto8gA.js";import{_ as e}from"./chunks/DIS.DdpTdGGD.js";import{_ as s,a as n}from"./chunks/M-S-LCS-AC5a.MFTz2ahv.js";import{_ as a}from"./chunks/OFF.BrU7kQE-.js";import{_ as r}from"./chunks/M-S-DS2l2.BdmWUi3X.js";import{_ as i}from"./chunks/EN.P9aPnFBv.js";import{_ as l,o as p,c,a3 as d}from"./chunks/framework.g9mfNVRQ.js";const C=JSON.parse('{"title":"Advanced Calibration","description":"","frontmatter":{},"headers":[],"relativePath":"calibrate/advancedcal.md","filePath":"calibrate/advancedcal.md"}'),m={name:"calibrate/advancedcal.md"};function u(b,t,g,h,f,y){return p(),c("div",null,[...t[0]||(t[0]=[d('<p>This menu provides some important settings and mechanisms for calibration.</p><div class="admonition xdrip"><p class="admonition-title"><img src="'+o+'" style="zoom:75%;"></p><p> Settings<br>  Less Common Settings<br>   Advanced Calibration</p></div><h5 id="use-treatment-bg-values" tabindex="-1">Use Treatment BG values <a class="header-anchor" href="#use-treatment-bg-values" aria-label="Permalink to &quot;Use Treatment BG values&quot;">​</a></h5><p>You can decide to use BG <a href="./../use/mainUI.html#treatments">treatments</a> (blood tests) as calibrations.</p><div class="admonition xdripitem"><p class="admonition-title">Use Treatment BG values</p><p> Choose whether to calibrate with the BG value in a Treatment entry</p></div><div class="warning custom-block"><p class="custom-block-title">Warning</p><p>Always using treatments as calibrations is <strong>not recommended</strong>.</p></div><p>Automatic mode will only suggest you use the treatment as a calibration if xDrip detects that current conditions are good to calibrate (like BG stable for 20 minutes, low noise).</p><div class="admonition xdripitem"><p class="admonition-title">Use Treatment BG values</p><p> Automatic mode (best)<span style="float:right;">● </span>   <br>  Ask me every time<span style="float:right;">○ </span>   <br>  Never use them<span style="float:right;">○ </span>   <br>  Always use them<span style="float:right;">○ </span>   </p></div><p>It might also suggest you enable automatic calibration.</p><p><strong>It is not recommended to use this feature with G6/G7/1/1+ sensors.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Enable automatic calibration</p><p> Entered blood tests which occur during flat trend periods can automatically be used to recalibrate after 20 minutes. This should provide the most accurate method to calibrate with.</p><p> Do you want to enable this feature?</p><p> <span style="background-color:white;color:black;"> NO </span>    YES, ENABLE</p></div><p>Ask me every time will do exactly this every time you enter a BG treatment.</p><div class="admonition xdripitem"><p class="admonition-title">Use BG for calibration?</p><p> Do you want to use this entered finger-stick blood glucose test to calibrate with?</p></div><p>Never use treatments will never use them to calibrate (and will prevent you from transforming a <a href="./../use/mainUI.html#treatments">treatment</a> into a calibration).</p><h5 id="automatic-calibration" tabindex="-1">Automatic Calibration <a class="header-anchor" href="#automatic-calibration" aria-label="Permalink to &quot;Automatic Calibration&quot;">​</a></h5><p>It is recommended to <strong>disable this for G6/G7/1/1+ sensors</strong>.</p><p>Automatic calibration will accept a treatment as a calibration if it satisfies the conditions of a flat trend for 20 minutes.</p><div class="admonition xdripitem"><p class="admonition-title">Automatic Calibration <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Calibrate using new blood glucose readings if the conditions appear right to do so without asking confirmation (experimental)</p></div><h3 id="plugins" tabindex="-1">Plugins <a class="header-anchor" href="#plugins" aria-label="Permalink to &quot;Plugins&quot;">​</a></h3><p>Calibration plugins are available in xDrip, most are not used anymore. If enabled, a plugin acts instead of the standard xDrip calibration. The idea was to have a customizable calibration algorithm selection but was never fully implemented. In general, a sensor needing a plugin to be calibrated should be replaced for safety reasons.</p><div class="warning custom-block"><p class="custom-block-title"><strong>SAFETY</strong></p><p><strong>Calibration safety mechanisms do not apply to plugins. Using a plugin to bypass calibration failure is dangerous.</strong></p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration Plugin</p><p> Experimental secondary calibration plugin</p></div><div class="warning custom-block"><p class="custom-block-title">Wear extension</p><p>Plugins are not fully implemented in Wear. You might see different values on your watch.</p></div><div class="admonition xdripitem"><p class="admonition-title">Calibration Plugin</p><p> None<br>  Datricsae - pronounced: da-trix-ee - highly experimental<br>  Fixed Slope Example - never use for real data<br>  xDrip Original - classic algorithm<br>  Last7Ua - Unweighted last 7 calibrations. Example only</p></div><p><strong><code>None</code></strong> by default the xDrip algorithm is used. <strong>Recommended</strong></p><p><strong><code>Datricsae</code></strong> was popular with those in trouble with default xDrip algorithm. It requires 8 calibration points (if less than 4 the original xDrip algorithm will be used) and has slope limits between 0.5 and 1.7. Its main strength is to remove outliers (bad calibration points) that fall too far out of the calibration line. Once filtered, if the number of calibration points falls below 4 or slope is out of limits, the classic xDrip algorithm is used.<br> Be careful as noisy calibrations might lead to inconsistent results.</p><img src="'+s+'" style="zoom:75%;"><p><strong><code>Fixed slope</code></strong> is an empty plugin returning slope 1.08 and intercept -5. <strong>Do not use it for real BG.</strong></p><p><strong><code>xDrip Original</code></strong> was the plugin equivalent of the xDrip algorithm. It doesn&#39;t do anything other than the xDrip algorithm. <strong>There is no added value in using it.</strong></p><p><strong><code>Last 7 unweighted</code></strong> was an early attempt to improve the original algorithm. It requires at least 4 calibrations (uses up to the last 7; below 4, current xDrip algorithm is used). <strong>Not recommended.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Plugin plot on graph <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Show glucose results from the plugin on the main graph</p></div><p>Enable if you want xDrip to plot results using the plugin.</p><img src="'+r+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Use Plugin Glucose <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> Main glucose display number comes from plugin!</p></div><p>Enable if you want the main BG number to be from plugin results. A circled P will show.</p><img src="'+n+'" style="zoom:75%;"><div class="admonition xdripitem"><p class="admonition-title">Plugin Override ALL <span class="symbol"><img src="'+a+'" style="zoom:75%;"></span></p><p> ALL new glucose data will be calculated and saved from the selected plugin and not from the standard xDrip algorithm. This is untested and may be inaccurate and buggy. Use with extreme caution.</p></div><p>Not implemented.</p><h3 id="calibrations" tabindex="-1">Calibrations <a class="header-anchor" href="#calibrations" aria-label="Permalink to &quot;Calibrations&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Double Calibrations <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Ask for a second optional initial calibration blood test</p></div><p>If you&#39;re not actually performing two different blood tests for initial calibration: disable this.</p><p>Old school calibration mode restores the original, narrower range of allowed slopes within the xDrip classic calibration algorithm (pre-2017), making default slopes more likely. Only visible with Engineering Mode enabled.</p><div class="admonition xdripitem"><p class="admonition-title">Old school calibration mode <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Original narrower range of allowed slopes within xDrip classic calibration algorithm (pre-2017). Default slopes more likely!</p></div><div class="admonition xdripitem"><p class="admonition-title">Infrequent Calibration <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> If needed, use calibrations from longer ago, e.g. if calibrations are supplied infrequently.</p></div><p>Calibrations get ignored when too old, if you calibrate rarely and want older calibration measurements to weigh on the current calibration curve: enable this.</p><h3 id="libre-specific" tabindex="-1">Libre specific <a class="header-anchor" href="#libre-specific" aria-label="Permalink to &quot;Libre specific&quot;">​</a></h3><h5 id="non-fixed-libre-slopes" tabindex="-1">Non-fixed Libre Slopes <a class="header-anchor" href="#non-fixed-libre-slopes" aria-label="Permalink to &quot;Non-fixed Libre Slopes&quot;">​</a></h5><div class="admonition xdripitem"><p class="admonition-title">Non-fixed Libre Slopes <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Enable to allow variable slopes with Libre collection methods</p></div><p>Libre sensors might be difficult to calibrate. If you cannot manage to get full range accuracy or never calibrate in the higher range, disable this and make the slope equal to 1. This is recommended for beginners.</p><p><strong>Always calibrate at stable glucose when in the lower normal range for safety.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Check Libre Serial <span class="symbol"><img src="'+i+'" style="zoom:75%;"></span></p><p> Automatically stop if Libre Serial changes unexpectedly</p></div><p>Carrying forward calibrations from the old sensor to a new one is dangerous. <strong>Leave this enabled.</strong></p><h3 id="bypass-quality-check" tabindex="-1">Bypass quality check <a class="header-anchor" href="#bypass-quality-check" aria-label="Permalink to &quot;Bypass quality check&quot;">​</a></h3><div class="admonition xdripitem"><p class="admonition-title">Bypass quality check <span class="symbol"><img src="'+e+'" style="zoom:75%;"></span></p><p> Allow initial calibration even if we don&#39;t have good enough data. Beware could result in inaccurate calibration.</p></div><p>During preliminary measurements for first calibration, 3 valid measurements are required. If they are missing or fail safety values, xDrip will wait. Enabling this will allow calibration without checking. <strong>Not recommended.</strong></p><div class="admonition xdripitem"><p class="admonition-title">Collecting Initial Readings</p><p> ✔ Data Collector Running<br>  ✔ Receiving Data from MiaoMiao Collector<br>  ✔ Received Some Recent Data<br>  ⧖ Received Enough Good Data to Calibrate<br>  <strong>Need 3 recent readings, got only 1 so far</strong><br>  Next reading expected in 1 minute</p></div><br><p><a href="https://github.com/NightscoutFoundation/xDrip/releases/tag/2026.11.21" target="_blank" rel="noreferrer"><em>Last modified 23/11/2026</em></a></p>',58)])])}const A=l(m,[["render",u]]);export{C as __pageData,A as default};
